1	/**
2	 * The `install` stage: resolve the lane's own closure, under declared policy.
3	 *
4	 * Spike C measured two npm decisions on the first unseen application and named
5	 * them as manual residue: "Two operator decisions per application before the
6	 * first build. Both are mechanisable as policy, and both are today unwritten
7	 * judgment" (`evidence/spikes/thin-wrapper-cost/verdict.json`, finding C3). The
8	 * first was a 2020 lockfile carrying an `https` tarball dependency, which modern
9	 * npm refuses with `EALLOWREMOTE`; the second was install scripts, which modern
10	 * npm skips by default, so the tree installed "without its native build ever
11	 * being attempted".
12	 *
13	 * Both are policies here, not judgment. Each has a declared flag, each defaults
14	 * to *not applied*, and a closure that needs one it was not given is a named
15	 * refusal rather than an operator reading a wall of npm output and deciding. The
16	 * defaults are the honest ones: this flow does not widen a package manager's own
17	 * safety default on an operator's behalf, and it does not install a tree whose
18	 * native build was silently skipped and call it installed.
19	 *
20	 * The policy findings are read out of the lockfile before anything runs, so the
21	 * refusal arrives before the network is touched rather than after a failed
22	 * install.
23	 */
24	
25	import { execFile } from 'node:child_process';
26	import { readdir } from 'node:fs/promises';
27	import { promisify } from 'node:util';
28	import * as path from 'pathe';
29	import { parseURL } from 'ufo';
30	import { directoryExists, fileExists, readJsonFile } from './analyze.ts';
31	import { refuse } from './refusals.ts';
32	
33	const run = promisify(execFile);
34	
35	/** The registry npm resolves a plain dependency from. */
36	export const DEFAULT_REGISTRY_HOST = 'registry.npmjs.org';
37	
38	/** The lockfiles this stage can install from, in the order it looks for them. */
39	export const NPM_LOCKFILES: readonly string[] = Object.freeze([
40		'package-lock.json',
41		'npm-shrinkwrap.json',
42	]);
43	
44	/** Lockfiles that name a package manager this stage's policies do not cover. */
45	export const FOREIGN_LOCKFILES: Readonly<Record<string, string>> = Object.freeze({
46		'bun.lockb': 'bun',
47		'yarn.lock': 'yarn',
48		'pnpm-lock.yaml': 'pnpm',
49	});
50	
51	export type InstallPolicy = Readonly<{
52		/** Carry npm's `--allow-remote` allowance for non-registry tarballs. */
53		allowRemoteTarballs: boolean;
54		/** Run the closure's install scripts, so a native build is attempted. */
55		allowInstallScripts: boolean;
56		/** Skip them, as a declared decision rather than as npm's silent default. */
57		skipInstallScripts: boolean;
58		/**
59		 * Install through a peer-dependency conflict.
60		 *
61		 * The third policy, and the one this repository measured rather than
62		 * inherited: a lane whose manifest now declares a current build toolchain
63		 * beside an era application's own pins can fail npm's peer resolution
64		 * outright (`ERESOLVE`). Carrying the allowance is a decision about what the
65		 * lane's closure is allowed to be, so it is declared like the other two.
66		 */
67		allowPeerConflicts: boolean;
68	}>;
69	
70	export const DEFAULT_INSTALL_POLICY: InstallPolicy = Object.freeze({
71		allowRemoteTarballs: false,
72		allowInstallScripts: false,
73		skipInstallScripts: false,
74		allowPeerConflicts: false,
75	});
76	
77	export type LockfileFindings = Readonly<{
78		lockfile: string;
79		lockfileVersion: number;
80		/** Dependencies resolved from somewhere other than the npm registry. */
81		remoteTarballDependencies: readonly string[];
82		/** Packages the lockfile marks as carrying an install script. */
83		installScriptPackages: readonly string[];
84	}>;
85	
86	const INSTALL_NOT_ESTABLISHED: readonly string[] = Object.freeze([
87		'An install resolves a closure. It is not a build, and it is not evidence that the closure works: nothing here establishes that any package in it compiles or runs.',
88		'The policy findings are read from the lockfile. A lockfile that does not mark an install script, or that resolves through a mirror this reading does not recognise, yields a finding this stage did not make.',
89		'`installScriptPackages` counts packages the lockfile declares an install script for. Whether a given script would have built anything on this host is not established here.',
90		'`closure: resolve` means the lane manifest declares a build toolchain the recorded lockfile predates, so npm resolved rather than replayed. The application’s own pins still come from the lockfile; what was newly resolved is what the manifest rewrite added, and that resolution is not a pin this repository recorded.',
91	]);
92	
93	function hostOf(value: string): string | null {
94		if (!value.startsWith('http://') && !value.startsWith('https://')) return null;
95		const parsed = parseURL(value);
96		return parsed.host ?? null;
97	}
98	
99	/** Read the two policy-bearing facts out of an npm lockfile. */
100	export function readLockfileFindings(
101		lockfile: string,
102		document: Record<string, unknown>,
103	): LockfileFindings {
104		const remote = new Set<string>();
105		const scripts = new Set<string>();
106		const lockfileVersion =
107			typeof document.lockfileVersion === 'number' ? document.lockfileVersion : 1;
108		const packages = document.packages as Record<string, unknown> | undefined;
109		if (packages !== undefined)
110			for (const key of Object.keys(packages).sort()) {
111				const entry = packages[key] as Record<string, unknown> | undefined;
112				if (entry === undefined || entry === null) continue;
113				const resolved = typeof entry.resolved === 'string' ? entry.resolved : null;
114				const host = resolved === null ? null : hostOf(resolved);
115				if (host !== null && host !== DEFAULT_REGISTRY_HOST)
116					remote.add(`${key === '' ? '.' : key} <- ${resolved ?? ''}`);
117				if (entry.hasInstallScript === true) scripts.add(key === '' ? '.' : key);
118			}
119		const walk = (tree: Record<string, unknown> | undefined, prefix: string): void => {
120			if (tree === undefined || tree === null) return;
121			for (const name of Object.keys(tree).sort()) {
122				const entry = tree[name] as Record<string, unknown> | undefined;
123				if (entry === undefined || entry === null) continue;
124				const identifier = prefix === '' ? name : `${prefix}/${name}`;
125				const version = typeof entry.version === 'string' ? entry.version : '';
126				const resolved = typeof entry.resolved === 'string' ? entry.resolved : version;
127				const host = hostOf(resolved);
128				if (host !== null && host !== DEFAULT_REGISTRY_HOST)
129					remote.add(`${identifier} <- ${resolved}`);
130				if (entry.hasInstallScript === true) scripts.add(identifier);
131				walk(entry.dependencies as Record<string, unknown> | undefined, identifier);
132			}
133		};
134		walk(document.dependencies as Record<string, unknown> | undefined, '');
135		return Object.freeze({
136			lockfile,
137			lockfileVersion,
138			remoteTarballDependencies: Object.freeze([...remote].sort()),
139			installScriptPackages: Object.freeze([...scripts].sort()),
140		});
141	}
142	
143	/**
144	 * Whether the closure is replayed or resolved.
145	 *
146	 * `replay` is `npm ci`: the lockfile is installed exactly as recorded, and a
147	 * manifest that disagrees with it is an error. `resolve` is `npm install`, and
148	 * it is what a lane whose manifest this pipeline rewrote requires — the lane
149	 * declares a build toolchain the recorded lockfile predates, so there is no
150	 * recorded closure for it to replay. The application's own pins still come from
151	 * the lockfile; what is newly resolved is what the rewrite added.
152	 */
153	export type ClosureMode = 'replay' | 'resolve';
154	
155	export type InstallPlan = Readonly<{
156		packageManager: string;
157		lockfile: string;
158		closure: ClosureMode;
159		findings: LockfileFindings;
160		policy: InstallPolicy;
161		command: readonly string[];
162	}>;
163	
164	/**
165	 * Decide the install command for a lane, or refuse by name.
166	 *
167	 * Nothing runs here. The whole point is that every decision this stage would
168	 * otherwise ask an operator for is taken from the declared policy and the
169	 * lockfile before a registry is contacted.
170	 */
171	export async function planLaneInstall(
172		laneDir: string,
173		policy: InstallPolicy = DEFAULT_INSTALL_POLICY,
174		environment: NodeJS.ProcessEnv = process.env,
175		closure: ClosureMode = 'replay',
176	): Promise<InstallPlan> {
177		if (policy.allowInstallScripts && policy.skipInstallScripts)
178			refuse({
179				code: 'install.install-script-policy-conflicts',
180				message:
181					'Install: the install-script allowance and the install-script skip were both declared. They are opposite policies and this flow does not pick between two declarations.',
182				stage: 'install',
183				origin: 'pipeline',
184			});
185		if (environment.VERSIONLESS_NETWORK_MODE === 'offline')
186			refuse({
187				code: 'install.network-not-permitted',
188				message:
189					'Install: VERSIONLESS_NETWORK_MODE is offline, so this stage may not reach a registry. No closure was resolved and nothing was installed.',
190				stage: 'install',
191				origin: 'pipeline',
192			});
193		/**
194		 * Which lockfiles the lane actually carries, read before anything is said
195		 * about them. The order matters, and it is the order a reader would want:
196		 * an npm lockfile is looked for first, so that "there is nothing to install
197		 * from" is only ever said about a lane where that is true.
198		 */
199		let lockfile: string | null = null;
200		for (const name of NPM_LOCKFILES)
201			if (lockfile === null && (await fileExists(path.join(laneDir, name)))) lockfile = name;
202		const foreign: string[] = [];
203		for (const name of Object.keys(FOREIGN_LOCKFILES).sort())
204			if (await fileExists(path.join(laneDir, name))) foreign.push(name);
205		/**
206		 * A lane pinned by another package manager *as well as* by npm. Both are
207		 * present, so this is not a lane missing a closure — it is a lane carrying
208		 * two, and the policies this stage holds are npm's.
209		 */
210		if (lockfile !== null && foreign.length > 0) {
211			const name = foreign[0] as string;
212			refuse({
213				code: 'install.package-manager-not-npm',
214				message: `Install: the lane carries ${name}, so its closure is pinned by ${FOREIGN_LOCKFILES[name] ?? 'another package manager'}. The two policies this stage carries — the remote-tarball allowance and the install-script allowance — are npm policies, and this flow does not translate them onto another package manager.`,
215				stage: 'install',
216				origin: 'pipeline',
217			});
218		}
219		/**
220		 * A lockfile is present and this stage does not read it. Saying `absent`
221		 * here would be false: the application pinned its closure, it pinned it
222		 * with a package manager whose lockfile this stage cannot read, and those
223		 * are different findings for an operator deciding what to do next.
224		 */
225		if (lockfile === null && foreign.length > 0)
226			refuse({
227				code: 'install.lockfile-foreign',
228				message: `Install: the lane carries ${foreign.join(', ')}, and this stage reads ${NPM_LOCKFILES.join(', ')}. The closure is pinned — by ${FOREIGN_LOCKFILES[foreign[0] as string] ?? 'another package manager'} — and it is pinned in a lockfile this flow does not read, so it is not absent and it is not installable here.`,
229				stage: 'install',
230				origin: 'pipeline',
231			});
232		if (lockfile === null)
233			refuse({
234				code: 'install.lockfile-absent',
235				message: `Install: the lane carries none of ${NPM_LOCKFILES.join(', ')}, so there is no pinned closure to install. This flow installs a recorded closure rather than resolving a new one.`,
236				stage: 'install',
237				origin: 'pipeline',
238			});
239		const document = await readJsonFile(path.join(laneDir, lockfile));
240		if (document === null)
241			refuse({
242				code: 'install.lockfile-unreadable',
243				message: `Install: ${lockfile} is not readable as a JSON object, so the closure it pins cannot be read and no install policy can be checked against it.`,
244				stage: 'install',
245				origin: 'pipeline',
246			});
247		const findings = readLockfileFindings(lockfile, document);
248		if (findings.remoteTarballDependencies.length > 0 && !policy.allowRemoteTarballs)
249			refuse({
250				code: 'install.remote-tarball-policy-not-declared',
251				message: `Install: the lockfile resolves ${String(findings.remoteTarballDependencies.length)} dependency(ies) from outside ${DEFAULT_REGISTRY_HOST}, first ${findings.remoteTarballDependencies[0] ?? ''}. Modern npm refuses those with EALLOWREMOTE unless the remote-tarball allowance is declared. Declare --allow-remote-tarballs to carry that policy; this flow does not take the allowance on an operator's behalf.`,
252				stage: 'install',
253				origin: 'pipeline',
254			});
255		if (
256			findings.installScriptPackages.length > 0 &&
257			!policy.allowInstallScripts &&
258			!policy.skipInstallScripts
259		)
260			refuse({
261				code: 'install.install-script-policy-not-declared',
262				message: `Install: the lockfile declares ${String(findings.installScriptPackages.length)} package(s) carrying an install script, first ${findings.installScriptPackages[0] ?? ''}. Modern npm skips them by default, which produces a tree whose native build was never attempted. Declare --allow-install-scripts to run them or --skip-install-scripts to record the skip as a decision; this flow does not let the default stand unnamed.`,
263				stage: 'install',
264				origin: 'pipeline',
265			});
266		const command = [
267			'npm',
268			closure === 'replay' ? 'ci' : 'install',
269			'--no-audit',
270			'--no-fund',
271			...(policy.allowRemoteTarballs ? ['--allow-remote', 'all'] : []),
272			...(policy.allowInstallScripts ? ['--foreground-scripts'] : ['--ignore-scripts']),
273			...(policy.allowPeerConflicts ? ['--legacy-peer-deps'] : []),
274		];
275		return Object.freeze({
276			packageManager: 'npm',
277			lockfile,
278			closure,
279			findings,
280			policy,
281			command: Object.freeze(command),
282		});
283	}
284	
285	export type InstallRecord = Readonly<{
286		stage: 'install';
287		ran: boolean;
288		/** Why the stage did not run, when it did not. */
289		reason: string | null;
290		packageManager: string | null;
291		lockfile: string | null;
292		closure: ClosureMode | null;
293		policy: InstallPolicy;
294		remoteTarballDependencies: readonly string[];
295		installScriptPackages: readonly string[];
296		command: readonly string[] | null;
297		exitCode: number | null;
298		/** Packages present in the lane's installed closure afterwards. */
299		installedPackages: number | null;
300		notEstablished: readonly string[];
301	}>;
302	
303	/** The record for a stage the run did not ask for. */
304	export function installNotRequested(reason: string): InstallRecord {
305		return Object.freeze({
306			stage: 'install',
307			ran: false,
308			reason,
309			packageManager: null,
310			lockfile: null,
311			closure: null,
312			policy: DEFAULT_INSTALL_POLICY,
313			remoteTarballDependencies: Object.freeze([]),
314			installScriptPackages: Object.freeze([]),
315			command: null,
316			exitCode: null,
317			installedPackages: null,
318			notEstablished: INSTALL_NOT_ESTABLISHED,
319		});
320	}
321	
322	/** How many packages the lane's installed closure carries, or null. */
323	export async function installedPackageCount(laneDir: string): Promise<number | null> {
324		const modules = path.join(laneDir, 'node_modules');
325		if (!(await directoryExists(modules))) return null;
326		let count = 0;
327		for (const entry of await readdir(modules, { withFileTypes: true })) {
328			if (!entry.isDirectory() || entry.name === '.bin') continue;
329			if (!entry.name.startsWith('@')) {
330				count += 1;
331				continue;
332			}
333			for (const scoped of await readdir(path.join(modules, entry.name), { withFileTypes: true }))
334				if (scoped.isDirectory()) count += 1;
335		}
336		return count;
337	}
338	
339	/**
340	 * Run the install this stage planned.
341	 *
342	 * A non-zero exit here is a **defect**, not a refusal: the policies were
343	 * declared, the closure was pinned, and the install still failed. Scoring that
344	 * as a refusal would let a broken tree be counted as a named, expected outcome.
345	 */
346	export async function runLaneInstall(
347		laneDir: string,
348		policy: InstallPolicy = DEFAULT_INSTALL_POLICY,
349		environment: NodeJS.ProcessEnv = process.env,
350		closure: ClosureMode = 'replay',
351	): Promise<InstallRecord> {
352		const plan = await planLaneInstall(laneDir, policy, environment, closure);
353		const [binary, ...args] = plan.command as readonly [string, ...string[]];
354		try {
355			await run(binary, args, { cwd: laneDir, env: environment, maxBuffer: 64 * 1024 * 1024 });
356		} catch (error) {
357			const detail = error instanceof Error ? error.message : String(error);
358			/**
359			 * One npm failure is a policy question rather than a breakage: a peer
360			 * conflict is npm reporting that the closure it was asked for is not
361			 * one it will assemble by default. That is a decision, so it is a named
362			 * refusal an operator can count and answer with a flag. Every other
363			 * failure is a defect.
364			 */
365			if (detail.includes('ERESOLVE') && !policy.allowPeerConflicts)
366				refuse({
367					code: 'install.peer-resolution-policy-not-declared',
368					message: `Install: npm refused the lane closure with ERESOLVE — a peer dependency conflict between the application's own era pins and the build toolchain the lane now declares. Declare --allow-peer-conflicts to install through it, which is a decision about what the lane's closure may be, or change what the lane declares. This flow does not take that decision on an operator's behalf.`,
369					stage: 'install',
370					origin: 'pipeline',
371				});
372			throw new Error(
373				`install: ${plan.command.join(' ')} failed in the lane. This is a defect rather than a refusal: the declared policies were applied and the pinned closure still did not install. ${detail}`,
374			);
375		}
376		return Object.freeze({
377			stage: 'install',
378			ran: true,
379			reason: null,
380			packageManager: plan.packageManager,
381			lockfile: plan.lockfile,
382			closure: plan.closure,
383			policy,
384			remoteTarballDependencies: plan.findings.remoteTarballDependencies,
385			installScriptPackages: plan.findings.installScriptPackages,
386			command: plan.command,
387			exitCode: 0,
388			installedPackages: await installedPackageCount(laneDir),
389			notEstablished: INSTALL_NOT_ESTABLISHED,
390		});
391	}
